           {"type": "parachute", "diameter_m": 4.0, "cd": 0.8, "deploy_event": "apogee", "material": "Ripstop nylon", "position_from_top_m": 0.12},
           {"type": "motor_mount", "outer_diameter_m": 0.0992, "length_m": 1.06, "wall_thickness_m": 0.0006, "material": "Fiberglass",
            "motor": {"manufacturer": "Cesaroni Technology Inc.", "designation": "14005N1100-P", "delay_s": null},
            "overhang_m": 0.02, "centering_ring_count": 2, "centering_ring_material": "Plywood (birch)"},
           {"type": "trapezoidal_fins", "count": 4, "root_chord_m": 0.32, "tip_chord_m": 0.13, "span_m": 0.16, "sweep_m": 0.12, "thickness_m": 0.004, "material": "Carbon fiber", "offset_from_aft_m": 0.02}
         ]}
      ]
    }
  ]
}
</design>
